// Decide que reportes tocan hoy (diario siempre; semanal los lunes; mensual el dia 1)
// y arma un HTML por cada uno, listo para convertir a PDF.
const bob = $('ObtenerBobinas').all().map(i => i.json);
const prods = $input.all().map(i => i.json);

const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const ayer = new Date(hoy.getTime() - 86400000);
const iso = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

const periodos = [{ nombre: 'diario', desde: iso(ayer), hasta: iso(ayer), titulo: 'Reporte diario ' + iso(ayer) }];
if (hoy.getDay() === 1) {
  const d1 = new Date(hoy.getTime() - 7 * 86400000);
  periodos.push({ nombre: 'semanal', desde: iso(d1), hasta: iso(ayer), titulo: 'Reporte semanal ' + iso(d1) + ' al ' + iso(ayer) });
}
if (hoy.getDate() === 1) {
  const m = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);
  periodos.push({ nombre: 'mensual', desde: iso(m), hasta: iso(ayer), titulo: 'Reporte mensual ' + iso(m).slice(0, 7) });
}

const out = [];
for (const p of periodos) {
  const bs = bob.filter(b => b.fecha >= p.desde && b.fecha <= p.hasta);
  const ps = prods.filter(x => x.fecha >= p.desde && x.fecha <= p.hasta);
  if (bs.length === 0 && ps.length === 0) continue;

  const kilos = bs.reduce((a, b) => a + (Number(b.peso) || 0), 0);
  const bien = bs.filter(b => b.estado === 'BIEN').length;
  const mal = bs.filter(b => b.estado === 'MAL').length;
  const se = ps.reduce((a, x) => a + (Number(x.scrap_empalme) || 0), 0);
  const sr = ps.reduce((a, x) => a + (Number(x.scrap_rollo) || 0), 0);
  const bultos = ps.reduce((a, x) => a + (Number(x.bultos) || 0), 0);
  const fmt = n => (Number(n) || 0).toLocaleString('es-AR');
  const pct = n => kilos ? (100 * n / kilos).toFixed(2) + '%' : '-';

  const agr = (arr, k, f) => {
    const o = {};
    for (const x of arr) { const key = x[k] || 'S/D'; o[key] = (o[key] || 0) + f(x); }
    return Object.entries(o).sort((a, b) => b[1] - a[1]);
  };
  const kilosMaq = agr(bs, 'maquina', b => Number(b.peso) || 0);
  const kilosOp = agr(bs, 'operario_bobina', b => Number(b.peso) || 0);

  const fila = (a, v) => '<tr><td>' + a + '</td><td style="text-align:right">' + v + '</td></tr>';
  const tabla = (titulo, filas) => '<table><tr><th colspan="2">' + titulo + '</th></tr>' + filas + '</table>';

  const html = '<!doctype html><html><head><meta charset="utf-8"><style>' +
    'body{font-family:Arial,sans-serif;margin:36px;color:#222}h1{font-size:20px;border-bottom:2px solid #333;padding-bottom:8px}' +
    'table{border-collapse:collapse;width:100%;margin:14px 0}td,th{border:1px solid #999;padding:6px 10px;font-size:12px}' +
    'th{background:#efefef;text-align:left}' +
    '</style></head><body>' +
    '<h1>' + p.titulo + '</h1>' +
    tabla('Resumen',
      fila('Kilos producidos', fmt(kilos)) +
      fila('Bobinas', bs.length) +
      fila('Peso promedio', bs.length ? fmt(Math.round(kilos / bs.length)) : '-') +
      fila('BIEN / MAL', bien + ' / ' + mal) +
      fila('Bultos (pallets)', fmt(bultos)) +
      fila('Scrap empalme', fmt(se) + ' (' + pct(se) + ')') +
      fila('Scrap rollo', fmt(sr) + ' (' + pct(sr) + ')') +
      fila('Scrap total', fmt(se + sr) + ' (' + pct(se + sr) + ')')) +
    tabla('Kilos por maquina', kilosMaq.map(([k, v]) => fila('Maq. ' + k, fmt(v))).join('')) +
    tabla('Kilos por operario', kilosOp.map(([k, v]) => fila(k, fmt(v))).join('')) +
    '<p style="font-size:10px;color:#888">Generado automaticamente el ' + iso(hoy) + '</p>' +
    '</body></html>';

  out.push({
    json: { periodo: p.nombre, titulo: p.titulo },
    binary: { archivo: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html') }
  });
}

return out;

// Detalle de bobinas de ayer para exportar a Excel (una fila por bobina)
const bob = $('ObtenerBobinas').all().map(i => i.json);
const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const a = new Date(hoy.getTime() - 86400000);
const ayer = a.getFullYear() + '-' + String(a.getMonth() + 1).padStart(2, '0') + '-' + String(a.getDate()).padStart(2, '0');
const filas = bob.filter(b => b.fecha === ayer);
if (filas.length === 0) return [];
return filas.map(b => ({
  json: {
    fecha: b.fecha,
    turno: b.turno,
    maquina: b.maquina,
    operario: b.operario_bobina || b.operario_turno || '',
    n_bobina: b.n_bobina,
    peso: b.peso,
    estado: b.estado,
    defectos: b.defectos || '',
    medida: b.medida || ''
  }
}));
